'use strict';
let myProfile=null,profileAvatar='';
async function loadMyProfile(){if(!currentUser)return;const result=await api('profile');if(!currentUser||result.profile.id!==currentUser.id)return;myProfile=result.profile;profileAvatar=myProfile.avatar;const f=$('profileForm');f.elements.name.value=myProfile.name;$('profileEmail').textContent=myProfile.email||'Chưa bổ sung';$('profilePhone').textContent=myProfile.phone||'Chưa bổ sung';$('profileEmailStatus').textContent=myProfile.emailVerified?'Email đã xác nhận':'Email chưa xác nhận';$('profilePicture').src=profileAvatar||defaultAvatar;$('accountPicture').src=profileAvatar||defaultAvatar;$('profileError').textContent='';}
const defaultAvatar='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="128" height="128"><rect width="128" height="128" rx="64" fill="#f3e7ec"/><circle cx="64" cy="46" r="22" fill="#91596d"/><path d="M22 112a42 42 0 0 1 84 0" fill="#91596d"/></svg>');
$('avatarFile').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('Chọn ảnh JPG, PNG hoặc WebP nhỏ hơn 5 MB');const image=await createImageBitmap(file);const canvas=document.createElement('canvas');canvas.width=160;canvas.height=160;const c=canvas.getContext('2d'),side=Math.min(image.width,image.height);c.fillStyle='#fff';c.fillRect(0,0,160,160);c.drawImage(image,(image.width-side)/2,(image.height-side)/2,side,side,0,0,160,160);image.close();profileAvatar=canvas.toDataURL('image/jpeg',0.8);$('profilePicture').src=profileAvatar;$('profileError').textContent='';}catch(e){$('profileError').textContent=e.message;}};
$('removeAvatar').onclick=()=>{profileAvatar='';$('profilePicture').src=defaultAvatar;$('avatarFile').value='';};
$('profileForm').onsubmit=async event=>{event.preventDefault();const f=event.target,b=f.querySelector('button.primary');b.disabled=true;try{await api('profile',{name:f.elements.name.value,avatar:profileAvatar});await refreshState();toast('Đã cập nhật hồ sơ');}catch(e){$('profileError').textContent=e.message;}finally{b.disabled=false;}};
async function showEmployeeProfile(id){try{const result=await api('profile?id='+encodeURIComponent(id)),p=result.profile;$('viewProfileName').textContent=p.name;$('viewProfileUsername').textContent=p.username;$('viewProfileEmail').textContent=p.email||'Chưa bổ sung';$('viewProfilePhone').textContent=p.phone||'Chưa bổ sung';$('viewProfileStatus').textContent=p.emailVerified?'Email đã xác nhận':'Email chưa xác nhận';$('viewProfilePicture').src=p.avatar||defaultAvatar;$('viewProfileDialog').showModal();}catch(e){toast(e.message);}}
$('resendEmail').onclick=async()=>{const f=$('authForm'),button=$('resendEmail');if(!f.reportValidity())return;button.disabled=true;try{await api('resend-email',{username:f.elements.username.value,password:f.elements.password.value});toast('Đã gửi email xác nhận, kiểm tra hộp thư và thư rác');}catch(e){$('authError').textContent=e.message;}finally{button.disabled=false;}};
if(location.pathname==='/verify-email'){const token=new URLSearchParams(location.hash.slice(1)).get('token');history.replaceState(null,'','/');api('verify-email',{token}).then(()=>toast('Email đã xác nhận. Bạn có thể đăng nhập sau khi quản lý duyệt.')).catch(e=>{$('authError').textContent=e.message;});}
if(currentUser)loadMyProfile().catch(e=>toast(e.message));
